gaea(){return"\u062f\u0627\u0648\u0627\u06a9\u0627\u0631\u06cc\u06cc \u0632\u06c6\u0631 \u0628\u06c6 \u0646\u0627\u0631\u062f\u0646\u06cc \u06a9\u06c6\u062f\u06cc \u067e\u0634\u062a\u0695\u0627\u0633\u062a\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5."},
gaeb(){return"\u0647\u06d5\u0648\u06b5\u06cc \u0632\u06c6\u0631 \u0628\u06c6 \u067e\u0634\u062a\u0695\u0627\u0633\u062a\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5."},
aeW(a){return"\u062f\u0648\u0627\u06cc "+a+" \u0686\u0631\u06a9\u06d5 \u062f\u0648\u0648\u0628\u0627\u0631\u06d5 \u0647\u06d5\u0648\u06b5 \u0628\u062f\u06d5\u0631\u06d5\u0648\u06d5."},
