aeT(a){return"\u062f\u0648\u0627\u06cc "+a+" \u0695\u06c6\u0698 \u062f\u0648\u0648\u0628\u0627\u0631\u06d5 \u0647\u06d5\u0648\u06b5 \u0628\u062f\u06d5\u0631\u06d5\u0648\u06d5."},
