ga69(){return"\u067e\u0627\u0631\u06d5\u062f\u0627\u0646\u06d5\u06a9\u06d5 \u062a\u06d5\u0648\u0627\u0648 \u0628\u06a9\u06d5 \u06cc\u0627\u0646 \u0628\u06cc\u067e\u0634\u06a9\u0646\u06d5"},
ga68(){return"\u067e\u06d5\u0695\u06d5\u06cc \u067e\u0627\u0631\u06d5\u062f\u0627\u0646 \u0628\u06a9\u06d5\u0631\u06d5\u0648\u06d5 \u0628\u06c6 \u062a\u06d5\u0648\u0627\u0648\u06a9\u0631\u062f\u0646\u06cc\u060c \u0626\u06d5\u06af\u06d5\u0631 \u067e\u0627\u0631\u06d5\u062a \u062f\u0627\u0648\u06d5 \u067e\u0627\u0631\u06d5\u062f\u0627\u0646\u06d5\u06a9\u06d5 \u0628\u067e\u0634\u06a9\u0646\u06d5."},
gUz(){return"\u0646\u06d5\u062e\u0634\u06d5\u06cc\u06d5\u06a9 \u0644\u06d5 \u0644\u06cc\u0633\u062a\u06d5\u06a9\u06d5 \u0647\u06d5\u06b5\u0628\u0698\u06ce\u0631\u06d5"},
gadA(){return"\u06af\u06d5\u0634\u062a\u06cc 3D"},
gae3(){return"\u0648\u0631\u062f\u06d5\u06a9\u0627\u0631\u06cc\u06cc\u06d5\u06a9\u0627\u0646\u062a \u0628\u06c6 \u062f\u06d5\u0646\u06ce\u0631\u06cc\u0646 \u0648 \u062f\u0648\u0627\u06cc \u067e\u0634\u062a\u0695\u0627\u0633\u062a\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5 \u067e\u0627\u06a9\u06ce\u062c\u06d5\u06a9\u06d5 \u0686\u0627\u0644\u0627\u06a9 \u062f\u06d5\u06a9\u06d5\u06cc\u0646"},
gUx(){return"\u062f\u0627\u0648\u0627\u06a9\u0627\u0631\u06cc \u067e\u0627\u0631\u06d5\u062f\u0627\u0646 \u0646\u06ce\u0631\u062f\u0631\u0627 \u2014 \u0686\u0627\u0648\u06d5\u0695\u06ce\u06cc \u067e\u0634\u062a\u0695\u0627\u0633\u062a\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc \u062a\u06cc\u0645\u06d5\u06a9\u06d5\u06cc\u0646"},
gadF(){return"\u0644\u06d5 \u0648\u0627\u062a\u0633\u0626\u0627\u067e \u0628\u06d5\u062f\u0648\u0627\u062f\u0627\u0686\u0648\u0648\u0646 \u0628\u06a9\u06d5"},
agh(a){return"\u062f\u0627\u0648\u0627\u06a9\u0627\u0631\u06cc \u067e\u0627\u0631\u06d5\u062f\u0627\u0646\u0645 \u0628\u06c6 \u067e\u0627\u06a9\u06ce\u062c\u06cc \xab"+a+"\xbb \u0646\u0627\u0631\u062f \u0648 \u0686\u0627\u0648\u06d5\u0695\u06ce\u06cc \u0686\u0627\u0644\u0627\u06a9\u06a9\u0631\u062f\u0646\u06cc\u0645."},
ga3E(){return"\u0686\u0627\u0648\u06d5\u0695\u06ce\u06cc \u0686\u0627\u0644\u0627\u06a9\u06a9\u0631\u062f\u0646"},
